/** True when the token is still valid but expires within `windowSeconds`. */
export function isAboutToExpire(
  payload: Pick<TokenPayload, 'exp'>,
  windowSeconds: number = 300,
  nowMs: number = Date.now(),
): boolean {
  const remaining = payload.exp - Math.floor(nowMs / 1000);
  return remaining > 0 && remaining <= windowSeconds;
}

